lemma FilterEvenOrder(s: seq<int>, x: int, y: int)
  requires x in s && y in s && IsEven(x) && IsEven(y)
  requires IdxOf(s, x) <= IdxOf(s, y)
  ensures IdxOf(FilterEven(s), x) <= IdxOf(FilterEven(s), y)
{
  var rest := FilterEven(s[1..]);
  if s[0] == x {
    assert FilterEven(s) == [x] + rest;
