    FilterEvenOrder(s[1..], x, y);
    if IsEven(s[0]) {
      var f := [s[0]] + rest;
      assert FilterEven(s) == f;
      assert f[1..] == rest;
    } else {
      assert FilterEven(s) == rest;
    }
